SELECT rel.id AS id, rel.sku_id AS skuId, sku.sku_code AS skuCode, sku.sku_name AS skuName, sku.spec_snapshot AS specSnapshot, rel.supplier_id AS supplierId, supplier.supplier_code AS supplierCode, supplier.supplier_name AS supplierName, rel.purchase_price AS purchasePrice, rel.delivery_cycle_day AS deliveryCycleDay, rel.min_order_qty AS minOrderQty, rel.supplier_sku_code AS supplierSkuCode, rel.default_flag AS defaultFlag, rel.enable_status AS enableStatus, rel.remark AS remark, rel.update_time AS updateTime FROM product_sku_supplier_rel rel INNER JOIN product_sku sku ON sku.id = rel.sku_id AND sku.corpid = rel.corpid AND sku.del = 0 INNER JOIN supplier supplier ON supplier.id = rel.supplier_id AND supplier.corpid = rel.corpid AND supplier.del = 0
ORDER BY rel.id DESC
LIMIT #{offset}, #{pageSize}
LIMIT #{pageSize}

SELECT supplier.id AS supplierId, supplier.supplier_code AS supplierCode, supplier.supplier_name AS supplierName FROM supplier supplier WHERE supplier.corpid = #{corpid} AND supplier.del = 0
AND supplier.id = #{supplierId}
ORDER BY supplier.id DESC
LIMIT #{limit}

